const { test } = require("node:test");
const assert = require("node:assert");
const { execFileSync } = require("node:child_process");
const path = require("node:path");

const CLI = path.join(__dirname, "..", "cli.js");

function run(...args) {
  return execFileSync(process.execPath, [CLI, ...args], {
    encoding: "utf8",
  });
}

test("--upper --repeat 3 prints HI on 3 lines, exit 0", () => {
  const out = run("--upper", "--repeat", "3", "hi");
  assert.strictEqual(out.split("\n").filter((l) => l === "HI").length, 3);
});

test("repeat defaults to 1 (single line)", () => {
  const out = run("--upper", "hi");
  assert.deepStrictEqual(out.split("\n").filter(Boolean), ["HI"]);
});

test("--repeat works without --upper", () => {
  const out = run("--repeat", "2", "hi");
  assert.deepStrictEqual(out.split("\n").filter(Boolean), ["hi", "hi"]);
});

test("flag order is order-independent", () => {
  const out = run("--repeat", "3", "--upper", "hi");
  assert.strictEqual(out.split("\n").filter((l) => l === "HI").length, 3);
});

test("invalid N exits 1 with an error on stderr", () => {
  for (const bad of ["0", "-1", "x", "2.5"]) {
    assert.throws(
      () => run("--upper", "--repeat", bad, "hi"),
      /error: --repeat expects a positive integer/,
    );
  }
});

